*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDSTF40301.xml";
scwin.notiId;
scwin.vSecugrpID = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    trs_Read.Action = "/ConsultationBookManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readConsultationBook&notiId=" + scwin.notiId;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_readConsultationBook,O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    dts_consultationBook.setCellData(dts_consultationBook.getRowPosition(), "SAVE_EMP_NO", js_emp_no);
    dts_consultationBook.setCellData(dts_consultationBook.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD", js_market);
    if (edt_Date.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장일자"));
        edt_Date.focus();
        return;
    }
    if (txb_isur_cd.getValue() == "") {
        $c.win.alert("[회사명]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    if (txb_doc_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        txb_doc_title.focus();
        return;
    }
    var fileYn = "N";
    for (i = 1; i <= dts_fileList.getTotalRow(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") != "") {
            fileYn = "Y";
        }
    }
    if (fileYn == "N") {
        $c.win.alert("첨부파일을 하나이상 등록해주세요");
        return;
    }
    var rtn = confirm('상장알림내역을 등록 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Save.Action = "/ConsultationBookManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createConsultationBook";
        trs_Save.KeyValue = "JSP(I:pInput=dts_consultationBook,I:pFile=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_update = function() {
    if (edt_Date.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장일자"));
        edt_Date.focus();
        return;
    }
    if (txb_isur_cd.getValue() == "") {
        $c.win.alert("[회사명]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    if (txb_doc_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        txb_doc_title.focus();
        return;
    }
    for (i = 0; i <= dts_fileList.getTotalRow(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") == "" && dts_fileList.getCellData(i, "filename") == "") {
            $c.cp.removeRow(dts_fileList, i);
        }
    }
    if (dts_fileList.getTotalRow() == 0) {
        $c.win.alert("첨부파일을 한개이상  입력해주세요.");
        return;
    }
    var rtn = confirm('상장알림내역을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Update.Action = "/ConsultationBookManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=modifyConsultationBook&notiId=" + scwin.notiId;
        trs_Update.KeyValue = "JSP(I:pInput1=dts_readConsultationBook,I:pInput2=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('상장알림내역을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_delConsultationBook.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_delConsultationBook.insertRow();
        dts_delConsultationBook.setCellData(1, "NOTI_ID", scwin.notiId);
        trs_Delete.Action = "/ConsultationBookManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=removeConsultationBook";
        trs_Delete.KeyValue = "JSP(I:pInput=dts_delConsultationBook)";
        trs_Delete.Post();
    }
};


//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + scwin.notiId + "&attach_seq=" + attach_seq + "&gubun=5";
};
scwin.fn_setDataHeader = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_SetSaveHeader = function() {
    // CUD용 Header
    dts_consultationBook.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LITMGT_CONMGT_INOUT";
    dts_consultationBook.Reset();
    dts_consultationBook.insertRow();
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    dts_consultationBook.setCellData(dts_consultationBook.getRowPosition(), "ISUR_CD", arrPar[0].ISUR_CD);
    txb_isur_cd.setValue(arrPar[0].COM_NM);
};
scwin.trs_Read_OnLoadError = function() {
    $c.stf.alert_error(trs_Read);
};
scwin.dts_readConsultationBook_OnLoadError = function() {
    $c.stf.alert_error(dts_readConsultationBook);
};
scwin.dts_readConsultationBook_OnLoadCompleted = function(rowcount) {
    if (dts_readConsultationBook.getCellData(dts_readConsultationBook.getRowPosition(), "KSD_CONFRM_RESERV_TP_NM") != "") {
        buttonSet.setErrorStatus();
    }
};
scwin.btn_search_onclick = function() {
    $c.lc.fn_PopFindCorpChrg(scwin.vSecugrpID);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "상장알림내역등록"));
    await $c.frame.CloseFrame(); //self.close();

};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "상장알림내역등록"));
    $c.win.alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "상장알림내역수정"));
    await $c.frame.CloseFrame(); //self.close();

};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "상장알림내역수정"));
    $c.win.alert(trs_Update.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "상장알림내역삭제"));
    await $c.frame.CloseFrame(); //self.close();

};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "상장알림내역삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.icn_Cal_onclick = function() {
    popUpCalendar2(edt_Date); //popUpCalendar(위치참조할ID, '값넣을마스크ID', '데이터포맷')

};
scwin.grd_userlist_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        $c.elw.fn_filedown(dts_fileList.getCellData(row, "SEQ"));
    }
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    if (scwin.notiId == "input") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        //dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        if (scwin.notiId == "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            //dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
            file_name.setValue(inf_find.getValue());
        }
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame(); //self.close();

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    buttonSet.setSaveInfo(btn_save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_modify, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_delete, fn_delete); // 삭제

    setInsertReadyStatus = "I";
    getId = $c.frame.path("../").fn_getId;
    scwin.notiId = getId();
    if (scwin.notiId != "input") {
        buttonSet.setUpdateStatus();
        scwin.fn_read();
    } else {
        buttonSet.setInsertStatus();
        txb_user_nm.setValue(js_emp_nm);
        scwin.fn_setDataHeader();
        scwin.fn_SetSaveHeader();
    }
};
